window.UP_CONTENT = window.UP_CONTENT || {};
(window.UP_CONTENT.facts = window.UP_CONTENT.facts || []).push(
  // ---------------- HISTORY ----------------
  { id: "hi01", topic: "history", headline: "Oxford University is older than the Aztec Empire", body: "Teaching was happening at Oxford by 1096. The Aztec capital, Tenochtitlan, was founded around 1325, and the Aztec Triple Alliance formed in 1428.", q: "Which came first: teaching at Oxford or the founding of the Aztec capital Tenochtitlan?", options: ["Teaching at Oxford", "Tenochtitlan, by far", "Both in one decade"], a: 0, explain: "Oxford has no single founding date; it grew rapidly after 1167, when Henry II banned English students from attending the University of Paris.", tip: "", legendary: true },
  { id: "hi02", topic: "history", headline: "Australia's army once fought emus with machine guns, and lost", body: "In 1932, soldiers with Lewis guns were sent to cull emus damaging wheat crops in Western Australia. The fast, scattering birds were hard to hit, and the operation failed to fix the problem.", q: "In 1932, Australia sent soldiers with machine guns to fight which enemy?", options: ["Kangaroo mobs", "Wild camels", "Feral rabbits", "Emu flocks"], a: 3, explain: "The officer in charge, Major Meredith, reportedly compared the birds' ability to absorb gunfire to that of tanks.", tip: "" },
  { id: "hi03", topic: "history", headline: "Ancient Romans used stale urine to clean their clothes", body: "Ammonia in aged urine breaks down grease, so Roman launderers (fullers) collected it in pots on the street. Emperor Vespasian even taxed its collection.", q: "Why did Roman launderers collect urine?", options: ["To dye togas a deep royal purple", "To keep moths out of wool cloth", "To soften rough wool fibres", "Its ammonia cut grease and dirt"], a: 3, explain: "The Latin phrase 'pecunia non olet' (money doesn't stink) is linked to Vespasian defending his urine tax.", tip: "" },
  { id: "hi04", topic: "history", headline: "The shortest recorded war lasted under an hour", body: "On 27 August 1896, Britain and Zanzibar fought the Anglo-Zanzibar War after a succession dispute. British warships shelled the palace and the sultan's side surrendered within about 40 minutes.", q: "Roughly how long did the 1896 Anglo-Zanzibar War last?", options: ["About 40 minutes", "About four days", "About four weeks"], a: 0, explain: "Estimates range from about 38 to 45 minutes, depending on when you start and stop the clock.", tip: "" },
  { id: "hi05", topic: "history", headline: "Peter the Great made Russian men pay a tax to keep their beards", body: "In 1698, Tsar Peter I, eager to westernize Russia, imposed a beard tax. Men who paid carried a token as proof they were allowed to keep their beards.", q: "What did Peter the Great tax to push Russians toward Western fashion?", options: ["Men's beards", "Long robes", "Fur hats", "Pointed shoes"], a: 0, explain: "Some beard tokens survive in museums; one style reportedly read 'The beard is a superfluous burden.'", tip: "" },
  { id: "hi06", topic: "history", headline: "Woolly mammoths were alive when the Great Pyramid was built", body: "Most mammoths died out about 10,000 years ago, but a small population survived on Russia's remote Wrangel Island until roughly 4,000 years ago. The Great Pyramid of Giza dates to about 2560 BCE.", q: "Where did the last known woolly mammoths survive until about 4,000 years ago?", options: ["Wrangel Island, Arctic Russia", "Interior Alaska, near the Yukon", "The far north of Scotland", "Iceland's remote highlands"], a: 0, explain: "A 2024 DNA study suggests the Wrangel herd descended from no more than about eight mammoths and lasted around 6,000 years.", tip: "", legendary: true },
  { id: "hi07", topic: "history", headline: "The Library of Alexandria didn't vanish in one great fire", body: "Historians now think the library declined over centuries: political purges, lost funding, and several damaging events, including a fire during Julius Caesar's siege in 48 BCE, all played a part.", q: "What do historians think mainly ended the Library of Alexandria?", options: ["A single fire set by Julius Caesar", "An earthquake and tsunami", "A flood of the Nile", "A slow decline over centuries"], a: 3, explain: "Scholars were expelled from Alexandria in 145 BCE by Ptolemy VIII, an early blow to the library's role as a center of learning.", tip: "" },
  { id: "hi08", topic: "history", headline: "The ancient Greeks built a gear-driven astronomical calculator", body: "The Antikythera mechanism, recovered from a shipwreck in 1901, used dozens of bronze gears to predict positions of the Sun and Moon and the timing of eclipses. It dates to roughly the 2nd or 1st century BCE.", q: "What did the ancient Antikythera mechanism mainly do?", options: ["Measure ocean depth for sailors", "Tell the hours like a water clock", "Encrypt military messages", "Model sky motions and eclipses"], a: 3, explain: "Nothing of comparable mechanical complexity is known again until medieval astronomical clocks over a thousand years later.", tip: "" },
  { id: "hi09", topic: "history", headline: "A volcano helped inspire the novel Frankenstein", body: "The 1815 eruption of Mount Tambora in Indonesia cooled the globe, making 1816 the 'Year Without a Summer'. Stuck indoors by storms near Lake Geneva, Mary Shelley began writing Frankenstein.", q: "Which event caused 1816's 'Year Without a Summer'?", options: ["The eruption of Mount Tambora", "A long dip in solar activity", "A large meteor impact in Siberia", "The eruption of Krakatoa"], a: 0, explain: "Krakatoa erupted later, in 1883. Tambora's eruption is the largest in recorded history.", tip: "" },
  { id: "hi10", topic: "history", headline: "In 1518, dozens of people in Strasbourg danced for days on end", body: "In July 1518, a woman began dancing in a Strasbourg street, and others joined over the following weeks. Officials even provided musicians and built a stage, thinking more dancing would cure it.", q: "How did Strasbourg officials first respond to the 1518 dancing plague?", options: ["Banned all music and dancing", "Hired musicians, built a stage", "Arrested and jailed the dancers", "Quarantined the whole city"], a: 1, explain: "The cause is still debated; mass psychogenic illness amid famine and disease is a leading explanation.", tip: "" },
  { id: "hi11", topic: "history", headline: "Railroads, not governments, first put the US on standard time", body: "Before 1883, towns set clocks by the local sun, so noon differed from city to city. On 18 November 1883, US and Canadian railroads switched to standard time zones to make schedules workable.", q: "Who first brought standard time zones into everyday use in the United States?", options: ["The US Congress", "The railroads", "The US Navy", "Telegraph companies"], a: 1, explain: "Congress didn't make time zones federal law until the Standard Time Act of 1918.", tip: "" },
  { id: "hi12", topic: "history", headline: "The Hundred Years' War lasted 116 years", body: "The conflict between England and France ran from 1337 to 1453, though it was really a series of wars broken up by truces and long pauses.", q: "How long did the Hundred Years' War between England and France actually last?", options: ["Exactly 100 years", "84 years", "116 years", "150 years"], a: 2, explain: "The name was coined much later, by 19th-century historians grouping the conflicts together.", tip: "" },
  { id: "hi13", topic: "history", headline: "The first recorded labor strike happened in ancient Egypt", body: "Around 1157 BCE, under Pharaoh Ramesses III, tomb builders at Deir el-Medina stopped work because their grain rations were late. A papyrus records their sit-in protests.", q: "Why did ancient Egyptian tomb builders stage the first recorded strike?", options: ["Their work hours were too long", "Unsafe conditions in the tombs", "A new pharaoh banned their gods", "Their grain rations were late"], a: 3, explain: "Workers were paid in grain and other goods, not coins. The account survives on the Turin Strike Papyrus.", tip: "" },
  { id: "hi14", topic: "history", headline: "Educated medieval Europeans knew the Earth was round", body: "The flat-Earth Middle Ages is largely a 19th-century myth. Scholars like Bede wrote of a spherical Earth, and a widely used 13th-century textbook was literally titled 'On the Sphere'.", q: "What did most educated people in medieval Europe believe about the Earth's shape?", options: ["It was round", "It was flat", "It was a cube", "They had no view"], a: 0, explain: "Aristotle argued for a round Earth around 350 BCE, citing the curved shadow Earth casts on the Moon during lunar eclipses.", tip: "" },
  { id: "hi15", topic: "history", headline: "Movable type was invented in China 400 years before Gutenberg", body: "Around 1040, Bi Sheng created movable type from baked clay. In Korea, the Jikji, printed in 1377 with metal type, is the oldest surviving book printed that way, decades before Gutenberg's Bible.", q: "Where was movable type for printing first invented?", options: ["China", "Germany", "Italy", "Egypt"], a: 0, explain: "Chinese has thousands of characters, which made movable type less of an advantage there than with a small alphabet.", tip: "" },
  { id: "hi16", topic: "history", headline: "Low ancient life expectancy was mostly about child deaths", body: "When average life expectancy was around 30, it wasn't because adults died at 30. Very high infant and child mortality dragged the average down; people who survived childhood often lived into their 50s, 60s, or beyond.", q: "Why was average life expectancy so low in much of the past?", options: ["Most adults died around 30", "Very high child mortality", "People were shorter", "Diets lacked meat"], a: 1, explain: "An average can mislead: a few deaths near age 0 pull the mean down far more than they affect a typical adult's life span.", tip: "" },
  { id: "hi17", topic: "history", headline: "The Inca ran a huge empire using knotted strings as records", body: "The Inca had no writing system in the usual sense. Instead they used quipus, cords with knots whose type and position encoded numbers for censuses, taxes, and storehouse records.", q: "What did the Inca use instead of writing to keep records?", options: ["Clay tablets with wedge marks", "Painted pottery with symbols", "Knotted cords called quipus", "Notches carved into bone"], a: 2, explain: "Knots used a base-10 positional system. Whether some quipus also recorded words or stories is still being studied.", tip: "" },
  { id: "hi18", topic: "history", headline: "The Rosetta Stone repeats one decree in three scripts", body: "Carved in 196 BCE, the stone carries the same decree in hieroglyphs, Demotic, and ancient Greek. Because scholars could read the Greek, it became the key to deciphering hieroglyphs.", q: "Why was the Rosetta Stone the key to reading Egyptian hieroglyphs?", options: ["It held a full hieroglyph dictionary", "It was written by Cleopatra", "It had pictures of each sign", "It showed the same text in Greek"], a: 3, explain: "Jean-Francois Champollion announced his breakthrough in 1822, building on earlier work by Thomas Young.", tip: "" },

  // ---------------- MONEY ----------------
  { id: "mo01", topic: "money", headline: "Divide 72 by a growth rate to see how fast money doubles", body: "The Rule of 72 is a shortcut: at 6% a year, money doubles in about 72/6 = 12 years. It's an approximation that works best for rates between about 4% and 12%.", q: "Using the Rule of 72, about how long does money take to double at 8% a year?", options: ["About 6 years", "About 9 years", "About 12 years", "About 18 years"], a: 1, explain: "The exact answer at 8% is about 9.01 years, so the shortcut is remarkably close.", tip: "Try this: divide 72 by your savings account's interest rate to see how many years it takes to double." },
  { id: "mo02", topic: "money", headline: "At 10% a year, money grows about 17 times in 30 years", body: "Compounding means growth earns growth. 1.10 multiplied by itself 30 times is about 17.4, so $1,000 becomes about $17,400, even though simple interest would give just $4,000.", q: "At 10% annual compound growth, roughly how much does $1,000 become in 30 years?", options: ["About $4,000", "About $8,000", "About $17,400", "About $30,000"], a: 2, explain: "Most of the growth comes late: in the final 10 years alone, the balance roughly multiplies by 2.6.", tip: "" },
  { id: "mo03", topic: "money", headline: "After a 50% loss, you need a 100% gain just to break even", body: "Losses and gains aren't symmetric. If $100 falls 50% to $50, getting back to $100 requires that $50 to double, a 100% gain.", q: "An investment drops 50%. What percentage gain does it need to get back to its starting value?", options: ["50%", "75%", "100%", "150%"], a: 2, explain: "A 20% loss needs a 25% gain; a 90% loss needs a 900% gain. Avoiding big drops matters more than it seems.", tip: "" },
  { id: "mo04", topic: "money", headline: "At 3% inflation, cash loses about a quarter of its value in 10 years", body: "Prices compound just like savings do. After 10 years at 3% inflation, prices are about 34% higher, so the same money buys only about 74% of what it used to.", q: "At 3% yearly inflation, roughly how much buying power does cash lose over 10 years?", options: ["About 3%", "About 10%", "About 26%", "About 50%"], a: 2, explain: "By the Rule of 72, prices double in about 24 years at 3% inflation, halving what idle cash can buy.", tip: "Try this: compare your savings rate to inflation; if it's lower, your cash is quietly shrinking." },
  { id: "mo05", topic: "money", headline: "Losing $100 hurts more than finding $100 feels good", body: "Kahneman and Tversky's research on loss aversion found that losses typically weigh about one and a half to two times as much as equal-sized gains. That's why people often reject fair coin-flip bets.", q: "What is loss aversion?", options: ["Losses hurt more than equal gains", "Fear of investing any money at all", "Preferring cash over credit cards", "Avoiding any risk, however tiny"], a: 0, explain: "Loss aversion is a core part of prospect theory, work for which Daniel Kahneman shared the 2002 Nobel Prize in economics.", tip: "Try this: before selling in a panic, ask if you'd buy the same asset today at this price." },
  { id: "mo06", topic: "money", headline: "Making saving the default more than doubled sign-ups in one study", body: "In a well-known 2001 study of one US company, retirement plan participation among new hires jumped from about 37% to 86% once workers were enrolled automatically and had to opt out instead of opt in.", q: "In a classic study, what most boosted retirement plan sign-ups among new hires?", options: ["Higher employer matching funds", "Automatic enrollment by default", "Free financial literacy classes", "Bonuses for signing up early"], a: 1, explain: "Defaults are powerful because doing nothing is the easiest choice; most people stuck with the default contribution rate too.", tip: "Try this: set up an automatic transfer to savings on payday so saving happens before you can spend it." },
  { id: "mo07", topic: "money", headline: "A 1% monthly interest rate costs about 12.7% a year, not 12%", body: "Monthly interest compounds: each month charges interest on the previous month's interest. 1.01 raised to the 12th power is about 1.127, so 1% a month equals about 12.7% annually.", q: "If debt charges 1% interest per month, about what is the effective yearly rate?", options: ["12.0%", "12.7%", "13.5%", "10.0%"], a: 1, explain: "That gap is the difference between APR (simple yearly rate) and APY or effective rate, which includes compounding.", tip: "Try this: when comparing loans or savings, look for the effective annual rate, which includes compounding." },
  { id: "mo08", topic: "money", headline: "The real price of anything is what you give up to get it", body: "Economists call this opportunity cost: the value of the best alternative you didn't choose. A $50 concert ticket really costs the $50 plus whatever else you could have done with that evening.", q: "What is the 'opportunity cost' of a choice?", options: ["The full price you pay for it", "The tax and fees added to it", "The best option you give up", "The value it loses over time"], a: 2, explain: "Opportunity cost explains why 'free' events can be expensive: they still cost your time and other options.", tip: "Try this: before a big purchase, name one specific thing you would do with that money instead." },
  { id: "mo09", topic: "money", headline: "Most professional fund managers fail to beat a simple index fund", body: "Over periods of 15 years or more, studies such as S&P's SPIVA reports consistently find that the large majority of actively managed stock funds trail their benchmark index, largely because of their higher fees.", q: "Over 15+ years, how do most actively managed stock funds compare with their index?", options: ["Most beat it", "About half beat it", "Most trail it", "They match it exactly"], a: 2, explain: "Even funds that win for a few years rarely keep winning; past outperformance is a weak predictor.", tip: "" },
  { id: "mo10", topic: "money", headline: "A 1% yearly fee can eat about a quarter of 30 years of savings", body: "Fees compound against you. Growing at 7% a year versus 6% (after a 1% fee) for 30 years leaves you with about 25% less money at the end.", q: "Over 30 years, about how much can a 1% annual fee cut your final savings?", options: ["About 1%", "About 5%", "About 10%", "About 25%"], a: 3, explain: "The math: (1.06 / 1.07) raised to the 30th power is about 0.75, so you keep only about three quarters.", tip: "Try this: look up the expense ratio of every fund you own and note any above 0.5%." },
  { id: "mo11", topic: "money", headline: "The joy of a raise fades as you get used to it", body: "Psychologists call it hedonic adaptation: people return toward their usual happiness after gains, so upgrades quickly feel normal. Lifestyle creep turns yesterday's luxuries into today's fixed costs.", q: "A big raise feels amazing, then normal within months. What is this called?", options: ["The wealth effect", "Diminishing marginal cost", "Money illusion", "Hedonic adaptation"], a: 3, explain: "The term 'hedonic treadmill' was coined by psychologists Philip Brickman and Donald Campbell in 1971.", tip: "Try this: when you get a raise, save at least half of it before your lifestyle adjusts." },
  { id: "mo12", topic: "money", headline: "Your brain treats a tax refund like 'free money', but it isn't", body: "Economist Richard Thaler named this mental accounting: we sort money into mental buckets and spend windfalls more freely than earned pay, even though a dollar is a dollar.", q: "You splurge your tax refund but would never spend your salary that way. Which concept is this?", options: ["Mental accounting", "Sunk cost fallacy", "Compound interest", "Opportunity cost"], a: 0, explain: "Thaler won the 2017 Nobel Prize in economics, partly for this work on how people actually handle money.", tip: "Try this: before spending a windfall, ask whether you'd spend the same amount from your paycheck." },
  { id: "mo13", topic: "money", headline: "Used cars sell for noticeably less just past 10,000-mile marks", body: "A study of millions of US wholesale used-car sales found prices drop sharply at each 10,000-mile threshold. Buyers focus on the leftmost digit, so 49,900 miles feels far better than 50,100.", q: "Why do used cars lose value sharply right after crossing 10,000-mile marks?", options: ["Warranties usually end right there", "Buyers fixate on the first digit", "Engines wear out at that mileage", "Taxes change at those mileages"], a: 1, explain: "This left-digit bias is also why so many prices end in .99: $4.99 tends to register as 'four-something'.", tip: "", legendary: true },
  { id: "mo14", topic: "money", headline: "Doubling a small income lifts well-being like doubling a big one", body: "Large surveys find that well-being tends to rise with the logarithm of income: going from $25,000 to $50,000 adds roughly as much as going from $100,000 to $200,000. The same dollars matter more when you have less.", q: "Research suggests well-being rises with income in what way?", options: ["Equally with each extra dollar", "Not at all above poverty", "With each doubling of income", "Only up to exactly $75,000"], a: 2, explain: "A famous 2010 study suggested a plateau around $75,000; later research found most people's happiness keeps rising with income.", tip: "" },
  { id: "mo15", topic: "money", headline: "When two monies circulate, people spend the worse one", body: "Gresham's law: if two coins have the same face value but one contains more precious metal, people hoard the valuable one and spend the other. 'Bad money drives out good.'", q: "Coins with the same face value but different silver content circulate. Which one do people spend?", options: ["The one with more silver", "The one with less silver", "Both at the same rate", "The newest-minted coins"], a: 1, explain: "When US mints stopped using silver in dimes and quarters in 1965, older silver coins quickly vanished from circulation.", tip: "" },
  { id: "mo16", topic: "money", headline: "Trade helps both sides even if one is better at everything", body: "David Ricardo's comparative advantage shows that if each side specializes in what it gives up least to produce, total output rises and both can gain from trading, even if one is more productive at every task.", q: "According to comparative advantage, what should each trading partner specialize in?", options: ["Whatever it can make fastest", "Whatever earns it the most money", "Goods it produces better than anyone", "Its lowest opportunity cost goods"], a: 3, explain: "Ricardo's 1817 example used England and Portugal trading cloth and wine.", tip: "" },
  { id: "mo17", topic: "money", headline: "Hungary's 1946 inflation doubled prices about every 15 hours", body: "After World War II, Hungary suffered the worst hyperinflation ever recorded. At its July 1946 peak, prices rose so fast that they roughly doubled every 15 hours.", q: "Which country holds the record for the worst hyperinflation in history?", options: ["Hungary, 1946", "Germany, 1923", "Zimbabwe, 2008", "Venezuela, 2018"], a: 0, explain: "Hungary printed a note for 100 quintillion pengo (a 1 with 20 zeros) and replaced the pengo with the forint in August 1946.", tip: "", legendary: true },
  { id: "mo18", topic: "money", headline: "A 2% raise during 4% inflation is a pay cut", body: "Money illusion is the habit of judging money by its face value instead of what it buys. If prices rise faster than your pay, your real income falls even as the number on your paycheck goes up.", q: "Your pay rises 2% while prices rise 4%. What happened to your real income?", options: ["It rose about 2%", "It stayed the same", "It fell about 2%", "It rose about 6%"], a: 2, explain: "The term 'money illusion' was popularized by economist Irving Fisher in his 1928 book of that name.", tip: "Try this: in salary talks, compare any raise to the current inflation rate, not to zero." },

  // ---------------- MIND ----------------
  { id: "mi01", topic: "mind", headline: "Money you've already spent shouldn't decide what you do next", body: "The sunk cost fallacy is continuing something because of what you've already invested. The ticket money is gone either way; the only real question is whether the next hour is worth it.", q: "You keep watching a bad movie only because you paid for the ticket. Which bias is this?", options: ["Anchoring", "Sunk cost fallacy", "Availability heuristic", "Hindsight bias"], a: 1, explain: "It's also called the Concorde fallacy, after the supersonic jet project that continued despite clear signs it would lose money.", tip: "Try this: ask 'If I were starting fresh today, would I choose this?' and act on that answer." },
  { id: "mi02", topic: "mind", headline: "A random spin of a wheel can sway your number guesses", body: "In a classic 1974 study, people spun a wheel rigged to land on 10 or 65, then guessed the share of UN countries that were African. Median guesses were 25% and 45%, pulled toward the irrelevant number.", q: "A salesperson opens at $900, so $600 feels like a bargain. Which bias is at work?", options: ["Confirmation bias", "Loss aversion", "Anchoring bias", "Mere exposure effect"], a: 2, explain: "Anchoring works even when people know the anchor is random, and even on experts like judges and real estate agents.", tip: "Try this: before seeing any price, write down what you think something is worth." },
  { id: "mi03", topic: "mind", headline: "We judge risk by how easily examples come to mind", body: "The availability heuristic makes vivid, heavily reported events, like plane crashes, feel more common than they are, while everyday risks like car travel feel safer, though they cause far more deaths per mile.", q: "After seeing news of a plane crash, you drive instead of fly, believing it's safer. Which bias?", options: ["Sunk cost fallacy", "Fundamental attribution error", "Peak-end rule", "Availability heuristic"], a: 3, explain: "One study estimated that extra US road deaths in the year after 9/11 came partly from people avoiding flying.", tip: "" },
  { id: "mi04", topic: "mind", headline: "Spreading out study sessions beats cramming for memory", body: "The spacing effect, first documented by Hermann Ebbinghaus in 1885, shows that reviewing material over several days produces far better long-term recall than the same time spent in one session.", q: "For long-term memory, what beats one long cramming session of the same total time?", options: ["Spaced reviews over days", "Rereading notes at high speed", "Studying with calm music on", "Highlighting the key lines"], a: 0, explain: "Ebbinghaus tested himself on nonsense syllables to measure forgetting, producing the first 'forgetting curve'.", tip: "Try this: review new material after 1 day, then 3 days, then a week." },
  { id: "mi05", topic: "mind", headline: "Testing yourself teaches you more than rereading", body: "The testing effect: pulling information out of memory strengthens it. In a 2006 study, students who practiced recalling a passage remembered much more a week later than those who reread it.", q: "Which study method most improves long-term memory, according to research?", options: ["Rereading the text several times", "Practicing recall from memory", "Highlighting the key passages", "Copying out notes neatly"], a: 1, explain: "Students who reread often felt more confident, even though they remembered less. Fluency is not the same as learning.", tip: "Try this: close the book and write down everything you remember before checking." },
  { id: "mi06", topic: "mind", headline: "People test their beliefs by looking for proof they're right", body: "In Peter Wason's 1960 2-4-6 task, people guessed a hidden number rule. Most tested only sequences fitting their own guess, so they rarely discovered the true rule: any increasing numbers.", q: "You only read news that supports your view and dismiss the rest. Which bias is this?", options: ["Hindsight bias", "Availability heuristic", "Confirmation bias", "Peak-end rule"], a: 2, explain: "The fastest way to test an idea is to look for a case that would prove it wrong.", tip: "Try this: for any strong opinion, find the best argument against it and state it fairly." },
  { id: "mi07", topic: "mind", headline: "After the fact, we believe we saw it coming all along", body: "Hindsight bias makes outcomes seem obvious once known. In 1970s studies, people recalled their earlier predictions about real events as closer to what actually happened than they had been.", q: "After a team loses, you insist you 'knew it all along', though you predicted a win. Which bias?", options: ["Survivorship bias", "Anchoring bias", "Sunk cost fallacy", "Hindsight bias"], a: 3, explain: "Hindsight bias can make us judge past decisions by their outcomes instead of what was knowable at the time.", tip: "" },
  { id: "mi08", topic: "mind", headline: "We underestimate how long tasks take, even with past experience", body: "The planning fallacy: in a 1994 study, students predicted they'd finish their theses in about 34 days; the average actually took about 56. We imagine the best-case plan and ignore past delays.", q: "You always think a report will take 2 hours, and it always takes 5. What is this called?", options: ["Planning fallacy", "Spotlight effect", "Mere exposure effect", "Anchoring"], a: 0, explain: "Hofstadter's law jokes: it always takes longer than you expect, even when you take into account Hofstadter's law.", tip: "" },
  { id: "mi09", topic: "mind", headline: "Studying only the winners can teach you exactly the wrong lesson", body: "Survivorship bias: in World War II, statistician Abraham Wald pointed out that damage on returning planes showed where planes could be hit and survive. The armor belonged where returning planes had no holes.", q: "You copy habits of famous dropouts, ignoring the many who dropped out and failed. Which bias?", options: ["Confirmation bias", "Survivorship bias", "Loss aversion", "Hindsight bias"], a: 1, explain: "The missing data, failures that never got studied, is often the most important part of the picture.", tip: "" },
  { id: "mi10", topic: "mind", headline: "Before you tear down a fence, find out why it was put up", body: "Chesterton's fence is a mental model from writer G.K. Chesterton: don't remove a rule or tradition until you understand why it exists. The reason may be hidden but still important.", q: "What does the mental model 'Chesterton's fence' advise?", options: ["Remove outdated rules quickly", "Add more fences to stay safe", "Learn why a rule exists first", "Never change any existing rule"], a: 2, explain: "It doesn't say rules can't change, only that the burden is on the reformer to understand the original reason first.", tip: "Try this: before deleting an odd step in a process, ask the person who added it." },
  { id: "mi11", topic: "mind", headline: "People notice your embarrassing shirt far less than you think", body: "The spotlight effect: in a 2000 study, students wearing a Barry Manilow T-shirt guessed about half the room noticed it. Only about a quarter actually did.", q: "You think everyone noticed your bad haircut, but few did. What is this called?", options: ["Fundamental attribution error", "Availability heuristic", "Peak-end rule", "Spotlight effect"], a: 3, explain: "We overestimate attention because we are the center of our own experience, and everyone else is busy being the center of theirs.", tip: "" },
  { id: "mi12", topic: "mind", headline: "We blame people's character and overlook their circumstances", body: "The fundamental attribution error: when someone cuts us off in traffic, we assume they're a jerk, rarely considering that they might be rushing to an emergency or simply didn't see us.", q: "A coworker is late and you assume they're lazy, never considering traffic. Which bias?", options: ["Fundamental attribution error", "Availability heuristic", "Planning fallacy", "Mere exposure effect"], a: 0, explain: "A 1967 study found people judged essay writers' true opinions from essays, even knowing the writers were assigned a side.", tip: "" },
  { id: "mi13", topic: "mind", headline: "Simply seeing something repeatedly makes you like it more", body: "The mere exposure effect, studied by Robert Zajonc in 1968, shows people tend to prefer things they've encountered more often, from words and faces to songs, even without noticing the repetition.", q: "A song you disliked at first grows on you after hearing it many times. Which effect?", options: ["Spotlight effect", "Mere exposure effect", "Availability heuristic", "Survivorship bias"], a: 1, explain: "It also helps explain why people often prefer their mirror image, while friends prefer their non-mirrored photo.", tip: "" },
  { id: "mi14", topic: "mind", headline: "People chose more pain when it ended a little less painfully", body: "In a 1993 study, people held a hand in painfully cold water for 60 seconds, and separately for 90 seconds where the last 30 were slightly warmer. Most chose to repeat the longer trial: we remember peaks and endings, not durations.", q: "Memories of an experience are shaped mostly by its most intense moment and its end. What is this?", options: ["Spacing effect", "Hindsight bias", "Peak-end rule", "Availability heuristic"], a: 2, explain: "This 'duration neglect' was also seen in colonoscopy patients, whose memories depended on how the procedure ended.", tip: "Try this: end meetings, trips, and workouts on a high note; it shapes how they're remembered.", legendary: true },
  { id: "mi15", topic: "mind", headline: "Mixing up practice problems feels harder but works better", body: "Interleaving means shuffling different problem types instead of practicing one type at a time. In a 2007 math study, students who practiced mixed problems scored far higher on a test a week later.", q: "Which practice approach led to better test scores in learning studies?", options: ["Drilling one problem type at a time", "Only the easiest problems", "Studying worked solutions only", "Mixing problem types together"], a: 3, explain: "Mixing forces you to identify which method a problem needs, the skill tests actually demand.", tip: "Try this: shuffle flashcards or practice problems from different chapters together." },
  { id: "mi16", topic: "mind", headline: "Half of viewers missed a person in a gorilla suit", body: "In a 1999 study, people counting basketball passes in a video often failed to notice a person in a gorilla suit walking through the scene. This inattentional blindness shows focus can hide the obvious.", q: "Why do people often miss unexpected things in plain sight while focused on a task?", options: ["Inattentional blindness", "Weak peripheral vision", "Short-term memory decay", "Confirmation bias"], a: 0, explain: "In the original study, the gorilla stayed on screen for about five seconds and even paused to thump its chest.", tip: "", legendary: true },
  { id: "mi17", topic: "mind", headline: "Imagining a plan already failed helps you spot its flaws", body: "A pre-mortem, a technique from psychologist Gary Klein, asks a team to imagine the project failed and explain why. It makes it safer to voice doubts and surfaces risks optimism hides.", q: "In a 'pre-mortem', what do you imagine before starting a project?", options: ["It has already succeeded", "It has already failed", "It will never start", "Its budget doubled"], a: 1, explain: "Imagining an outcome as already certain seems to make it easier to generate concrete explanations for it.", tip: "Try this: before a big decision, write three reasons it might fail one year from now." },
  { id: "mi18", topic: "mind", headline: "To solve a problem, ask how you'd guarantee failure", body: "Inversion is a mental model popularized by investor Charlie Munger, echoing mathematician Carl Jacobi's advice: 'invert, always invert.' Listing ways to fail reveals what to avoid.", q: "You want better sleep, so you list everything that would ruin it. Which mental model is this?", options: ["Sunk cost", "Anchoring", "Inversion", "Mere exposure"], a: 2, explain: "Avoiding obvious mistakes is often easier and more reliable than trying to be brilliant.", tip: "" },

  // ---------------- TECH ----------------
  { id: "te01", topic: "tech", headline: "A real moth was once taped into a computer's logbook as a 'bug'", body: "In 1947, operators of the Harvard Mark II found a moth stuck in a relay and taped it in the log as the 'first actual case of bug being found.' The word bug for a glitch was already in use.", q: "What was found inside the Harvard Mark II computer in 1947, famously logged as a 'bug'?", options: ["A cockroach", "A spider", "A beetle", "A dead moth"], a: 3, explain: "Thomas Edison used 'bug' for technical faults in the 1870s. The logbook page is held by the Smithsonian.", tip: "" },
  { id: "te02", topic: "tech", headline: "GPS would drift about 10 km a day without Einstein's relativity", body: "GPS satellite clocks tick about 38 microseconds a day faster than clocks on the ground, due to weaker gravity and their speed. Engineers correct for this; without it, positions would drift by kilometers daily.", q: "Why must GPS satellite clocks be adjusted using Einstein's theories of relativity?", options: ["Time ticks at a different rate", "Solar wind slows their clocks", "Signals bounce off the Moon", "They overheat in direct sunlight"], a: 0, explain: "Speed slows the satellite clocks by about 7 microseconds a day; weaker gravity speeds them by about 45, giving a net gain of 38.", tip: "", legendary: true },
  { id: "te03", topic: "tech", headline: "Almost all intercontinental internet traffic runs under the sea", body: "Satellites carry only a sliver. About 99% of data crossing oceans travels through fiber-optic cables on the seafloor, some thousands of kilometers long and about as thick as a garden hose.", q: "How does most internet data travel between continents?", options: ["Communication satellites", "Undersea fiber-optic cables", "High-altitude relay balloons", "Chains of radio towers"], a: 1, explain: "The first transatlantic telegraph cable was laid in 1858, but it failed after only about three weeks.", tip: "" },
  { id: "te04", topic: "tech", headline: "One of the first webcams was pointed at a coffee pot", body: "At the University of Cambridge in 1991, researchers set up a camera on a coffee pot so they could check if it was full without walking to the room. In 1993 it was put on the web.", q: "What did the famous Trojan Room webcam at Cambridge University show?", options: ["A fish tank", "A parking lot", "A coffee pot", "The weather outside"], a: 2, explain: "The pot was later auctioned on eBay in 2001 for about 3,350 pounds when the camera went offline.", tip: "" },
  { id: "te05", topic: "tech", headline: "CAPTCHA is an acronym for a test of humanity", body: "CAPTCHA stands for 'Completely Automated Public Turing test to tell Computers and Humans Apart'. It flips Alan Turing's idea: here a machine judges whether you're human.", q: "What is a CAPTCHA designed to do?", options: ["Encrypt your password", "Speed up page loading", "Verify your email", "Tell humans from bots"], a: 3, explain: "Some versions put human effort to work, such as reCAPTCHA, which once helped digitize words from old books.", tip: "" },
  { id: "te06", topic: "tech", headline: "QR codes were invented to track car parts", body: "In 1994, engineer Masahiro Hara at Denso Wave, a Toyota group company, created the QR code to scan car parts quickly. QR stands for 'Quick Response'.", q: "What were QR codes originally invented to do?", options: ["Track car parts in factories", "Let diners pay at restaurants", "Share website links on posters", "Scan airline boarding passes"], a: 0, explain: "Built-in error correction means many QR codes can still scan even when part of the code is damaged or covered.", tip: "" },
  { id: "te07", topic: "tech", headline: "Apollo's computer memory was woven by hand", body: "The Apollo Guidance Computer stored its programs in 'core rope memory': wires threaded through or around tiny magnetic rings by hand, each choice encoding a 1 or a 0. It had about 4 KB of working memory.", q: "How was the Apollo Guidance Computer's permanent program memory made?", options: ["Etched onto early silicon chips", "Hand-woven wire through rings", "Printed onto punched cards", "Stored on magnetic tape reels"], a: 1, explain: "Much of the weaving was done by skilled workers, many of them women, at Raytheon. Software had to be final months before launch.", tip: "", legendary: true },
  { id: "te08", topic: "tech", headline: "Your phone screen senses the electricity in your finger", body: "Most phones use capacitive touchscreens, which detect a change in an electric field when a conductive object like skin touches them. That's why ordinary gloves or a fingernail usually don't work.", q: "Why don't most touchscreens respond to a gloved finger?", options: ["Gloves are too soft to press", "Screens detect your body heat", "Screens sense conductive skin", "Gloves block a light sensor"], a: 2, explain: "Touchscreen gloves work by weaving conductive thread into the fingertips.", tip: "" },
  { id: "te09", topic: "tech", headline: "Adding letters to a password beats adding symbols", body: "Each extra character multiplies the possibilities. An 8-letter lowercase password has about 200 billion combinations; a 12-letter one has about 95 quadrillion, roughly 457,000 times more.", q: "Which usually makes a password harder to crack by guessing?", options: ["Swapping o for 0", "Adding your birth year", "Capitalizing the first letter", "Making it much longer"], a: 3, explain: "Predictable swaps like @ for a are built into cracking tools, so they add little strength.", tip: "Try this: use a password manager, or a passphrase of four or more random words." },
  { id: "te10", topic: "tech", headline: "Junk email is called spam because of a Monty Python sketch", body: "In a 1970 Monty Python sketch, a cafe's menu is overrun with Spam and a group of Vikings drowns out conversation by singing 'Spam' over and over. Early internet users borrowed the name for unwanted floods of messages.", q: "Where does the term 'spam' for junk messages come from?", options: ["A Monty Python comedy sketch", "An acronym for 'sent post'", "A 1990s computer virus name", "A brand of early email software"], a: 0, explain: "One of the first widely noticed commercial spams was a 1994 Usenet ad by two lawyers offering green card lottery services.", tip: "" },
  { id: "te11", topic: "tech", headline: "Bluetooth is named after a 10th-century Viking king", body: "Harald 'Bluetooth' Gormsson united Denmark and parts of Norway. In 1997, an engineer proposed his name for a tech meant to unite devices; the logo combines Harald's initials in runes.", q: "Who is the wireless technology Bluetooth named after?", options: ["A Swedish engineer", "A Danish king", "A Norse god", "A dentist"], a: 1, explain: "The name was meant to be temporary. Proposed alternatives included 'PAN' and 'RadioWire'.", tip: "" },
  { id: "te12", topic: "tech", headline: "The padlock in your browser doesn't mean a site is trustworthy", body: "HTTPS and the padlock mean your connection to the site is encrypted, so others can't easily read or alter data in transit. A scam site can have a padlock too.", q: "What does the padlock icon (HTTPS) in a browser actually guarantee?", options: ["The site is safe and legit", "The site has no viruses", "The connection is encrypted", "The site is government-approved"], a: 2, explain: "Free certificates made HTTPS nearly universal, which is great for privacy but means it's no longer a sign of legitimacy.", tip: "Try this: check the exact domain name spelling before entering a password, padlock or not." },
  { id: "te13", topic: "tech", headline: "The @ in email addresses was picked in 1971 for a simple reason", body: "Ray Tomlinson sent the first networked email between computers on ARPANET. He chose @ to separate the user from the computer's name because it meant 'at' and appeared in no one's name.", q: "Why did Ray Tomlinson choose the @ symbol for email addresses?", options: ["It looked like a little envelope", "It came from his company's logo", "It was the only spare key left", "It meant 'at' and was little used"], a: 3, explain: "Tomlinson said the first test messages were forgettable, something like 'QWERTYUIOP'.", tip: "" },
  { id: "te14", topic: "tech", headline: "Noise-canceling headphones fight sound with opposite sound", body: "Microphones pick up outside noise, and the headphones play a sound wave that is its mirror image. The peaks and troughs cancel out, a process called destructive interference.", q: "How do active noise-canceling headphones reduce noise?", options: ["They play an inverted sound wave", "Thick foam pads block the sound", "They lower the volume you hear", "They filter out speech frequencies"], a: 0, explain: "It works best on steady, low sounds like engine hum; sudden or high-pitched sounds are harder to cancel.", tip: "" },
  { id: "te15", topic: "tech", headline: "The first item scanned with a UPC barcode was chewing gum", body: "On 26 June 1974, at a supermarket in Troy, Ohio, a cashier scanned a 10-pack of Wrigley's Juicy Fruit gum, the first retail sale using a UPC barcode.", q: "What was the first product sold using a UPC barcode scan in 1974?", options: ["A can of tomato soup", "A pack of chewing gum", "A carton of fresh milk", "A box of breakfast cereal"], a: 1, explain: "That pack of gum is now kept at the Smithsonian's National Museum of American History.", tip: "" },
  { id: "te16", topic: "tech", headline: "Keeping your phone at 100% and hot wears its battery faster", body: "Lithium-ion batteries age faster when held at high charge and high temperature. Many phones now offer optimized charging that pauses around 80% to reduce this stress.", q: "Which habit speeds up wear on a lithium-ion phone battery?", options: ["Charging it in short bursts", "Unplugging before it's full", "Staying at 100% while hot", "Turning it off every night"], a: 2, explain: "Unlike old nickel-cadmium cells, lithium-ion batteries have no 'memory effect', so topping up often is fine.", tip: "Try this: turn on your phone's optimized or limited charging setting and avoid charging it under a pillow." },
  { id: "te17", topic: "tech", headline: "The first hard drive weighed about a ton and held under 4 MB", body: "IBM's 350 disk drive, launched in 1956 with the RAMAC computer, used fifty 24-inch platters to store about 3.75 MB. Companies leased it rather than bought it.", q: "About how much data could IBM's first hard drive, from 1956, store?", options: ["About 4 kilobytes", "About 4 megabytes", "About 4 gigabytes", "About 400 megabytes"], a: 1, explain: "That's roughly the size of a single MP3 song today.", tip: "" },
  { id: "te18", topic: "tech", headline: "Incognito mode hides your browsing from your device, not the internet", body: "Private browsing stops your browser from saving history, cookies, and form data after you close it. Your internet provider, employer network, and the sites you visit can still see your activity.", q: "Who can still see your activity when you use a browser's incognito mode?", options: ["No one, not even your browser", "Only the maker of your browser", "Only other people using your device", "Websites and your network provider"], a: 3, explain: "Files you download and bookmarks you save while in incognito mode still remain on your device.", tip: "" },

  // ---------------- CULTURE ----------------
  { id: "cu01", topic: "culture", headline: "Ketchup started as a fermented fish sauce", body: "The word likely comes from 'ke-tsiap', a fish sauce from southern China. British traders brought the idea home, making ketchups from mushrooms or walnuts before tomato ketchup took over in the 1800s.", q: "What was the original 'ketchup' made from?", options: ["Fermented fish", "Ripe tomatoes", "Red chili peppers", "Cooked apples"], a: 0, explain: "Tomato ketchup recipes appeared in the early 1800s; Heinz began selling its tomato ketchup in 1876.", tip: "" },
  { id: "cu02", topic: "culture", headline: "Being stolen helped make the Mona Lisa world-famous", body: "In 1911, Louvre worker Vincenzo Peruggia walked out with the painting. Its two-year absence made headlines worldwide, and it was recovered in Florence in 1913.", q: "Which event greatly boosted the Mona Lisa's worldwide fame?", options: ["Its 1960s tour of US museums", "Its 1911 theft from the Louvre", "Its sale to the king of France", "A Hollywood film in the 1950s"], a: 1, explain: "Crowds lined up at the Louvre just to see the empty space on the wall where the painting had hung.", tip: "" },
  { id: "cu03", topic: "culture", headline: "Carrots weren't always orange", body: "Early cultivated carrots, from Central Asia, were mostly purple or yellow. Orange varieties were developed and popularized by Dutch growers in the 1600s and later became the global standard.", q: "What colors were most early cultivated carrots?", options: ["Deep orange and red", "White and green", "Purple and yellow", "Black and blue"], a: 2, explain: "The popular story that the Dutch bred orange carrots to honor William of Orange has no solid evidence behind it.", tip: "" },
  { id: "cu04", topic: "culture", headline: "The word 'nice' once meant foolish", body: "'Nice' comes from Latin 'nescius', meaning ignorant. Over centuries in English it shifted through meanings like silly, shy, and fussy before settling on pleasant in the 1700s.", q: "What did the word 'nice' originally mean?", options: ["Kind and gentle", "Pretty or elegant", "Costly or luxurious", "Foolish or ignorant"], a: 3, explain: "A trace of its 'fussy, precise' phase survives in phrases like 'a nice distinction', meaning a fine or subtle one.", tip: "" },
  { id: "cu05", topic: "culture", headline: "Beethoven wrote his Ninth Symphony while profoundly deaf", body: "Beethoven's hearing declined from his late 20s. By the 1824 premiere of the Ninth, he was so deaf that a singer turned him around to see the audience applauding.", q: "What was unusual about Beethoven when he wrote his Ninth Symphony?", options: ["He was profoundly deaf", "He was still a teenager", "He had gone fully blind", "He couldn't read music"], a: 0, explain: "Beethoven used 'conversation books' in which visitors wrote their side of the conversation; many of them survive.", tip: "" },
  { id: "cu06", topic: "culture", headline: "The Olympics once gave medals for painting and poetry", body: "From 1912 to 1948, the Olympic Games held art competitions in architecture, literature, music, painting, and sculpture. Entries had to be inspired by sport.", q: "Which of these once earned Olympic medals, from 1912 to 1948?", options: ["Chess and checkers", "Painting and poetry", "Cooking and baking", "Ballroom and folk dancing"], a: 1, explain: "Modern Olympics founder Pierre de Coubertin won a gold for literature in 1912, entering under a pseudonym.", tip: "", legendary: true },
  { id: "cu07", topic: "culture", headline: "Flying buttresses let Gothic cathedrals become walls of glass", body: "Stone vaults push outward on walls. Flying buttresses, arched supports outside the building, carry that push away, so walls could be thinner and filled with huge stained-glass windows.", q: "What did flying buttresses allow Gothic cathedral builders to do?", options: ["Build deep crypts underground", "Build mostly in wood, not stone", "Have thin walls and big windows", "Build taller without any arches"], a: 2, explain: "Pointed arches helped too: they direct more of a vault's weight downward than round arches do.", tip: "" },
  { id: "cu08", topic: "culture", headline: "A 1,900-year-old dome is still the largest of its kind", body: "Rome's Pantheon, completed around 125 CE, has a dome about 43 meters across. It remains the world's largest unreinforced concrete dome.", q: "Which building has the world's largest unreinforced concrete dome?", options: ["Hagia Sophia, Istanbul", "St. Peter's Basilica", "Florence Cathedral", "The Pantheon in Rome"], a: 3, explain: "Romans used lighter material like pumice toward the top, and the dome thins to an open 'oculus' about 8 meters wide.", tip: "", legendary: true },
  { id: "cu09", topic: "culture", headline: "The word 'robot' comes from a Czech play about forced labor", body: "Karel Capek's 1920 play 'R.U.R.' introduced the word robot, from Czech 'robota', meaning forced labor. Capek credited his brother Josef with suggesting it.", q: "The word 'robot' comes from a Czech word meaning what?", options: ["Forced labor", "Metal servant", "Thinking machine", "Iron worker"], a: 0, explain: "Capek's robots were actually artificial biological beings, closer to what we'd now call androids.", tip: "" },
  { id: "cu10", topic: "culture", headline: "Italian food had no tomatoes until the 1500s", body: "Tomatoes are native to the Americas and reached Europe in the 16th century. Many Europeans grew them as curiosities, and tomato sauce recipes appear in Italy only around the late 1600s.", q: "Where did tomatoes originally come from?", options: ["Southern Italy", "The Americas", "The Middle East", "North Africa"], a: 1, explain: "One early Italian name for the tomato was 'pomodoro', meaning 'golden apple', suggesting early varieties were yellow.", tip: "" },
  { id: "cu11", topic: "culture", headline: "Piano is short for an instrument that plays 'soft-loud'", body: "The full name is pianoforte, Italian for 'soft-loud'. Built around 1700 by Bartolomeo Cristofori, it used hammers so players could control volume by touch, which the harpsichord couldn't do.", q: "Why was the piano originally called the 'pianoforte'?", options: ["It was very heavy to move", "It was first built in a fort", "It could play soft and loud", "It had two separate keyboards"], a: 2, explain: "A harpsichord plucks strings, so pressing the key harder doesn't make it louder.", tip: "" },
  { id: "cu12", topic: "culture", headline: "'Goodbye' is a shortened blessing", body: "Goodbye comes from 'God be with ye', squeezed over time into forms like 'godbwye'. The 'good' likely crept in by analogy with 'good day' and 'good night'.", q: "What phrase did the word 'goodbye' evolve from?", options: ["Good day to you", "Go by in peace", "Good night to ye", "God be with ye"], a: 3, explain: "Spanish 'adios' and French 'adieu' have a similar origin, meaning 'to God'.", tip: "" },
  { id: "cu13", topic: "culture", headline: "Top violinists often can't tell a Stradivarius from a new violin", body: "In blind tests published in 2012 and 2014, professional violinists playing old Italian and new violins couldn't reliably identify which was which and often preferred the new ones.", q: "In blind tests, how did top violinists judge Stradivarius violins against new ones?", options: ["Couldn't reliably tell them apart", "Always picked the Stradivarius", "Found new violins harsh and thin", "Said the Strads sounded far louder"], a: 0, explain: "Players wore modified goggles in dim light, so they couldn't see the instruments they were playing.", tip: "" },
  { id: "cu14", topic: "culture", headline: "Most 'wasabi' served outside Japan isn't real wasabi", body: "Real wasabi comes from a plant that is hard to grow and expensive. Most of the green paste served with sushi is horseradish mixed with mustard and green coloring.", q: "What is the green 'wasabi' paste served with sushi usually made from?", options: ["Mashed avocado and lime", "Horseradish and mustard", "Ground green tea leaves", "Seaweed and green chili"], a: 1, explain: "Real wasabi is usually grated fresh, and its flavor fades within about 15 minutes.", tip: "" },
  { id: "cu15", topic: "culture", headline: "Sushi began as a way to preserve fish in fermenting rice", body: "Early sushi, called narezushi, packed salted fish in rice for months; the fermenting rice preserved it and was often thrown away. Fast, fresh nigiri sushi emerged in Edo-era Tokyo, in the early 1800s.", q: "What was the original purpose of the rice in early sushi?", options: ["To decorate the plate", "To add a mild sweetness", "To preserve the fish", "To soak up fish oils"], a: 2, explain: "Funazushi, made from carp near Lake Biwa, is a fermented style still made in Japan today.", tip: "" },
  { id: "cu16", topic: "culture", headline: "The word 'emoji' has nothing to do with 'emotion'", body: "Emoji is Japanese: 'e' means picture and 'moji' means character. The resemblance to the English word emotion is a coincidence.", q: "What does the Japanese word 'emoji' literally mean?", options: ["Emotion icon", "Electronic image", "Little smiling face", "Picture character"], a: 3, explain: "An influential early set of 176 emoji, designed for a Japanese mobile service in 1999, is held by the Museum of Modern Art in New York.", tip: "" },
  { id: "cu17", topic: "culture", headline: "Fortune cookies most likely come from Japan, not China", body: "Researchers trace fortune cookies to Japanese crackers with fortunes tucked inside. Japanese-American bakers in California popularized them in the early 1900s, and they're rare in China.", q: "Where do fortune cookies most likely originate?", options: ["Japan", "China", "Korea", "Vietnam"], a: 0, explain: "Japanese bakeries near Kyoto still make similar cookies, called tsujiura senbei, which are larger and browner.", tip: "" },
  { id: "cu18", topic: "culture", headline: "The word 'quarantine' comes from the Italian for '40 days'", body: "During plague outbreaks in the 1300s and 1400s, ships arriving at Venice had to wait 40 days, 'quaranta giorni', before passengers could come ashore.", q: "What does the word 'quarantine' originally refer to?", options: ["A ship's quarantine flag", "A 40-day waiting period", "A Latin word for sickness", "A type of hospital"], a: 1, explain: "The nearby port city of Ragusa (now Dubrovnik) began with a 30-day isolation in 1377, later extended.", tip: "" }
);
